// Lightweight canvas detail and effects. All sizes are in map units.
import {COLORS} from './engine.js';
import {attackStyle} from './towerStyles.js';
const polygon=(c,points)=>{c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();};
const circle=(c,x,y,r)=>{c.beginPath();c.arc(x,y,r,0,Math.PI*2);};
function star(c,x,y,r,n=4,spin=0){polygon(c,Array.from({length:n*2},(_,i)=>{const a=spin+i*Math.PI/n,s=i%2?r*.3:r;return [x+Math.cos(a)*s,y+Math.sin(a)*s];}));}
export function modelDetail(c,def,x,y,size,time,ghost=false){const elements=def.elements.filter(e=>COLORS[e])||[],palette=elements.length?elements.map(e=>COLORS[e]):[COLORS[def.element]||COLORS.composite];c.save();c.globalAlpha=ghost?.5:1;const top=y-size*.58,r=size*.11;c.fillStyle='#08140c88';c.beginPath();c.ellipse(x,y+size*.035,size*.38,size*.09,0,0,Math.PI*2);c.fill();
 // A stepped foundation and individual element inlays make adjacent towers readable.
 c.strokeStyle='#bdd3a36b';c.lineWidth=Math.max(1,size*.022);c.beginPath();c.ellipse(x,y,size*.31,size*.09,0,0,Math.PI*2);c.stroke();palette.forEach((color,i)=>{const a=(i+.5)/palette.length*Math.PI*2;c.fillStyle=color;c.fillRect(x+Math.cos(a)*size*.24-size*.025,y+Math.sin(a)*size*.065-size*.025,size*.05,size*.04);});
 if(def.element==='composite'&&def.name!=='Periodic Tower of the Elements'){c.strokeStyle='#e6d4a5';c.lineWidth=size*.035;c.beginPath();c.moveTo(x-size*.14,top+size*.12);c.lineTo(x+size*.14,top+size*.12);c.stroke();c.restore();return;}
 const style=attackStyle(def);c.strokeStyle=palette[0];c.fillStyle=palette[0];c.lineWidth=size*.035;
 if(['water','steam','geyser','ice','hail'].includes(style)){polygon(c,[[x,top-r*1.5],[x+r,top],[x,top+r],[x-r,top]]);c.fill();c.strokeStyle='#d9faff';c.beginPath();c.moveTo(x,top-r);c.lineTo(x-r*.4,top);c.stroke();}
 else if(['leaf','roots','venom','acid','plague','mud'].includes(style)){for(const side of [-1,1]){c.beginPath();c.ellipse(x+side*r*.7,top,r*.75,r*.4,side*.7,0,Math.PI*2);c.fill();}c.strokeStyle='#edffd2';c.beginPath();c.moveTo(x-r,top+r);c.lineTo(x+r,top-r);c.stroke();}
 else if(['shell','rock','forge','gold','bone'].includes(style)){polygon(c,[[x-r,top+r*.5],[x-r*.6,top-r],[x+r*.7,top-r*.7],[x+r,top+r*.6]]);c.fill();c.fillStyle='#fff0c7';c.fillRect(x-r*.4,top-r*.5,r*.6,r*.3);}
 else if(['fire','napalm'].includes(style)){const sway=Math.sin(time*7+x)*r*.35;polygon(c,[[x-r,top+r],[x-r*.6,top],[x+sway,top-r*1.8],[x+r*.5,top-r*.3],[x+r,top+r]]);c.fill();c.fillStyle='#fff6b0';polygon(c,[[x-r*.35,top+r],[x,top-r*.6],[x+r*.35,top+r]]);c.fill();}
 else if(['glaive','lightning','laser','comet'].includes(style)){for(const side of [-1,1]){c.beginPath();c.moveTo(x,top);c.lineTo(x+side*size*.2,top-size*.08);c.lineTo(x+side*size*.14,top+size*.04);c.stroke();}star(c,x,top,r,4,time*.4);c.fill();}
 else{c.beginPath();c.ellipse(x,top,r*1.35,r*.8,time*.3,0,Math.PI*2);c.stroke();star(c,x,top,r,style==='rune'?6:4,time*.4);c.fill();}
 // Fusion towers carry all their constituent colors, not just their damage element.
 if(palette.length>1)palette.forEach((color,i)=>{const a=time*.45+i*Math.PI*2/palette.length;c.fillStyle=color;circle(c,x+Math.cos(a)*r*1.9,top+Math.sin(a)*r*.8,r*.3);c.fill();});c.restore();}
export function projectileEffect(c,e,screen,scale,time,busy=false){const q=Math.max(0,e.ttl/e.maxTTL),progress=1-q,start=screen(e.x,e.y),end=screen(e.tx,e.ty),palette=e.elements?.length?e.elements.map(v=>COLORS[v]).filter(Boolean):[e.color],colors=palette.length?palette:[e.color],style=e.style||'arrow',s=scale,radius=(17+(e.tier||1)*2)*s;if(e.originTower||e.type==='helix')start.y-=65*s;const angle=Math.atan2(end.y-start.y,end.x-start.x);c.save();c.globalAlpha=Math.min(1,q*3);c.lineCap='round';c.lineJoin='round';
 const beam=e.type==='beam'||e.type==='helix'||['laser','lightning'].includes(style);
 if(beam){const steps=style==='lightning'?10:18;c.strokeStyle=e.color;c.shadowColor=e.color;c.shadowBlur=busy?0:25*s;c.lineWidth=(style==='laser'?12:8)*s;c.beginPath();for(let i=0;i<=steps;i++){const f=i/steps,w=style==='lightning'?Math.sin(i*13+time*31)*26*s: e.type==='helix'?Math.sin(f*30-time*15)*18*s:0,x=start.x+(end.x-start.x)*f-Math.sin(angle)*w,y=start.y+(end.y-start.y)*f+Math.cos(angle)*w;i?c.lineTo(x,y):c.moveTo(x,y);}c.stroke();c.shadowBlur=0;c.lineWidth=2*s;c.strokeStyle='#f4ffff';c.stroke();if(e.type==='helix'){c.strokeStyle=colors.at(-1);c.lineWidth=4*s;c.beginPath();for(let i=0;i<=steps;i++){const f=i/steps,w=-Math.sin(f*30-time*15)*18*s,x=start.x+(end.x-start.x)*f-Math.sin(angle)*w,y=start.y+(end.y-start.y)*f+Math.cos(angle)*w;i?c.lineTo(x,y):c.moveTo(x,y);}c.stroke();}c.restore();return;}
 const travel=e.type==='boomerang'?(progress<.5?progress*2:2-progress*2):progress,arc=['shell','rock','mud','bone','gold'].includes(style)?Math.sin(travel*Math.PI)*90*s:0,x=start.x+(end.x-start.x)*travel,y=start.y+(end.y-start.y)*travel-arc;
 if(style!=='arrow'){const count=busy?3:7;for(let i=count;i>0;i--){const f=Math.max(0,travel-i*.025),px=start.x+(end.x-start.x)*f,py=start.y+(end.y-start.y)*f-(arc?Math.sin(f*Math.PI)*90*s:0);c.globalAlpha=Math.min(1,q*3)*(1-i/(count+1))*.55;c.fillStyle=colors[i%colors.length];circle(c,px,py,radius*(1-i/(count+2))*.8);c.fill();}}
 c.globalAlpha=Math.min(1,q*3);c.translate(x,y);c.rotate(['glaive','orbit','rune','mirror'].includes(style)?time*16:angle);c.fillStyle=e.color;c.strokeStyle=colors.at(-1);c.lineWidth=3*s;
 if(['fire','radiant','napalm','prismatic','plasma','laser','comet','nova'].includes(style)&&!busy){c.shadowColor=e.color;c.shadowBlur=30*s;}
 if(['fire','napalm'].includes(style)){polygon(c,[[-radius*2,radius*.45],[-radius*1.3,-radius*.5],[radius*.7,-radius*.35],[radius,0],[radius*.5,radius*.55],[-radius, radius*.7]]);c.fill();c.fillStyle='#fff4ae';polygon(c,[[-radius*.6,0],[radius*.65,-radius*.2],[radius*.9,0],[radius*.4,radius*.25]]);c.fill();c.shadowBlur=0;for(let i=0;i<3;i++){c.fillStyle=i%2?'#ffd777':'#fc7935';c.fillRect(-radius*(2+i*.65),Math.sin(time*20+i*4)*radius,3*s,3*s);}}
 else if(['radiant','prismatic','nova','plasma','comet'].includes(style)){star(c,0,0,radius,style==='prismatic'?6:4,time*6);c.fill();c.shadowBlur=0;c.fillStyle='#fffdf0';star(c,0,0,radius*.5);c.fill();}
 else if(['water','steam','geyser'].includes(style)){c.beginPath();c.ellipse(0,0,radius*1.3,radius*.6,0,0,Math.PI*2);c.fill();c.strokeStyle='#dcffff';c.beginPath();c.arc(0,0,radius*.7,-1.5,0);c.stroke();for(let i=0;i<2;i++){circle(c,-radius*(1.5+i),Math.sin(time*14+i)*radius,4*s);c.stroke();}}
 else if(['ice','hail'].includes(style)){polygon(c,[[radius*1.6,0],[-radius*.4,-radius*.65],[-radius,0],[-radius*.4,radius*.65]]);c.fill();c.strokeStyle='#e0fbff';c.beginPath();c.moveTo(-radius*.5,0);c.lineTo(radius,0);c.stroke();}
 else if(['leaf','roots','venom','acid','plague'].includes(style)){c.fillStyle=['venom','acid','plague'].includes(style)?'#a8e951':e.color;c.beginPath();c.ellipse(0,0,radius*1.25,radius*.55,.25,0,Math.PI*2);c.fill();c.strokeStyle=colors.at(-1);c.beginPath();c.moveTo(-radius,0);c.lineTo(radius,0);c.stroke();}
 else if(['rock','shell','mud','bone','gold','forge'].includes(style)){polygon(c,[[-radius,-radius*.4],[-radius*.3,-radius],[radius*.8,-radius*.6],[radius,radius*.5],[-radius*.4,radius]]);c.fill();c.fillStyle=style==='shell'?'#fff2d2':'#cdb68b';c.fillRect(-radius*.3,-radius*.6,radius*.8,radius*.3);}
 else if(style==='arrow'){c.strokeStyle='#e2d4ae';c.lineWidth=3*s;c.beginPath();c.moveTo(-radius*1.6,0);c.lineTo(radius,0);c.stroke();c.fillStyle='#f4ede0';polygon(c,[[radius*1.35,0],[radius*.5,-radius*.4],[radius*.5,radius*.4]]);c.fill();}
 else if(style==='glaive'){star(c,0,0,radius*1.4,3,time*8);c.fill();c.stroke();}
 else{c.strokeStyle=colors.at(-1);circle(c,0,0,radius);c.stroke();c.fillStyle=['void','arcane','spirit','mirror'].includes(style)?'#32204f':e.color;circle(c,0,0,radius*.75);c.fill();star(c,0,0,radius*.65,style==='rune'?6:4,time*5);c.fillStyle=colors[0];c.fill();}
 // Secondary colors remain visible on every fusion shot.
 if(colors.length>1){c.shadowBlur=0;colors.forEach((color,i)=>{const a=time*8+i*Math.PI*2/colors.length;c.fillStyle=color;circle(c,Math.cos(a)*radius*1.3,Math.sin(a)*radius*.9,4*s);c.fill();});}c.restore();}
export function areaEffect(c,e,screen,scale,time){const p=screen(e.x,e.y),q=Math.max(0,e.ttl/e.maxTTL),r=(e.radius||110)*scale*(1-q*.5),style=e.style||'',colors=e.elements?.length?e.elements.map(v=>COLORS[v]).filter(Boolean):[e.color];c.save();c.globalAlpha=q*.55;c.strokeStyle=e.color;c.fillStyle=e.color;c.lineWidth=3*scale;
 if(['steam','venom','acid','plague','mud'].includes(style)){for(let i=0;i<6;i++){const a=i*Math.PI/3;c.globalAlpha=q*.13;circle(c,p.x+Math.cos(a)*r*.45,p.y+Math.sin(a)*r*.45,r*.55);c.fill();}c.globalAlpha=q*.55;}
 circle(c,p.x,p.y,r);c.stroke();if(['water','geyser','ice','hail'].includes(style)){circle(c,p.x,p.y,r*.65);c.stroke();}
 const n=e.type==='death'?7:12;for(let i=0;i<n;i++){const a=i*Math.PI*2/n+time*.3,x=p.x+Math.cos(a)*r,y=p.y+Math.sin(a)*r;c.fillStyle=colors[i%colors.length]||e.color;c.strokeStyle=c.fillStyle;
 if(e.type==='burn'||['fire','napalm'].includes(style)){polygon(c,[[x-7*scale,y],[x+Math.sin(time*10+i)*4*scale,y-24*scale],[x+7*scale,y]]);c.fill();c.fillStyle='#ffd88d';c.fillRect(x-2*scale,y-9*scale,4*scale,8*scale);}
 else if(['ice','hail','nova'].includes(style)){c.beginPath();c.moveTo(p.x+Math.cos(a)*r*.7,p.y+Math.sin(a)*r*.7);c.lineTo(x,y);c.stroke();star(c,x,y,8*scale,4,a);c.fill();}
 else if(['rock','shell','bone'].includes(style)){c.beginPath();c.moveTo(p.x+Math.cos(a)*r*.2,p.y+Math.sin(a)*r*.2);c.lineTo(x-7*scale,y-4*scale);c.lineTo(x,y);c.lineTo(x+8*scale,y-6*scale);c.stroke();}
 else if(['roots','leaf'].includes(style)){c.beginPath();c.moveTo(p.x,p.y);c.quadraticCurveTo(x-15*scale,y+20*scale,x,y);c.stroke();c.beginPath();c.ellipse(x,y,9*scale,4*scale,a,0,Math.PI*2);c.fill();}
 else if(style==='lightning'){c.beginPath();c.moveTo(x,y);c.lineTo(x+10*scale,y-15*scale);c.lineTo(x-3*scale,y-10*scale);c.lineTo(x+7*scale,y-30*scale);c.stroke();}
 else if(['orbit','radiant','plasma','prismatic','rune'].includes(style)){star(c,x,y,10*scale,4,time*5);c.fill();}
 else c.fillRect(x-3*scale,y-3*scale,6*scale,6*scale);}
 c.restore();}

export function drawHurricane(c,t,def,screen,scale,time){const h=t.hurricane;if(!h)return;const p=screen(h.x,h.y),s=scale,colors=def.elements.map(e=>COLORS[e]);c.save();c.lineWidth=5*s;c.globalAlpha=.65;for(let i=0;i<7;i++){const y=p.y-i*30*s,r=(20+i*13)*s,spin=time*7+i*.8;c.strokeStyle=i%2?'#d9edef':colors[i%colors.length];c.beginPath();c.ellipse(p.x+Math.sin(spin)*8*s,y,r,9*s+i*2*s,0,spin,spin+Math.PI*1.7);c.stroke();}for(let i=0;i<8;i++){const a=time*5+i*.8,r=(30+i*8)*s;c.fillStyle=colors[i%colors.length];c.fillRect(p.x+Math.cos(a)*r,p.y-((time*70+i*25)%200)*s,5*s,4*s);}c.globalAlpha=.18;c.fillStyle='#d0e5de';c.beginPath();c.ellipse(p.x,p.y,80*s,20*s,0,0,Math.PI*2);c.fill();c.restore();}
